local config = {
  ui_story_32160401_1_dialog_content = "Hey, are we grabbing something to eat?",
  ui_story_32160401_2_dialog_content = "Yes! I thought about it and this seems the best way to thank you.",
  ui_story_32160401_3_dialog_content = "Otherwise, I'm gonna have to keep stuffing you with more gadgets.",
  ui_story_32160401_4_option_content = "No need to thank me at all.",
  ui_story_32160401_5_dialog_content = "I didn't help you for your gratitude.",
  ui_story_32160401_6_dialog_content = "After all, I love to see experts from all over the place get together and talk.",
  ui_story_32160401_7_dialog_content = "Because that's how we get more new ideas into the world.",
  ui_story_32160401_8_dialog_content = "That's exactly right!",
  ui_story_32160401_9_dialog_content = "But I still gotta reciprocate. Not doing so is just not me.",
  ui_story_32160401_10_option_content = "More gadgets aren't necessarily bad...",
  ui_story_32160401_11_dialog_content = "I'm actually quite fond of them...",
  ui_story_32160401_12_dialog_content = "Just ignore the snobs who called them \"trendy trash\"!",
  ui_story_32160401_13_dialog_content = "You'd settle for gadgets? Um... Good to know. It's a recognition, isn't it?",
  ui_story_32160401_14_dialog_content = "Maybe I'll slip you a couple more after we're done with the meal...",
  ui_story_32160401_15_dialog_content = "You look like you know a thing or two about making stuff. How about we talk over the meal?",
  ui_story_32160401_16_dialog_content = "Sure, I've been wanting to hear your take on Longzhou craftsmanship.",
  ui_story_32160401_17_dialog_content = "So, how's the food here?",
  ui_story_32160401_18_dialog_content = "Fantastic! Never thought street food could be so delicious.",
  ui_story_32160401_19_dialog_content = "You said you wanted a diner that a real Longzhou local would pick...",
  ui_story_32160401_20_dialog_content = "And that means a hole-in-the-wall tucked away in a back alley somewhere.",
  ui_story_32160401_21_dialog_content = "Getting customers to come back on taste alone is the true measure of a good eatery!",
  ui_story_32160401_22_dialog_content = "True, I can tell you speak from experience.",
  ui_story_32160401_23_dialog_content = "However, I never expected you to be so keen on the topic of food, Xuan Ji.",
  ui_story_32160401_24_dialog_content = "I was planning on taking this opportunity to discuss the secrets of gadgetry.",
  ui_story_32160401_25_dialog_content = "But up to this point, all we've been talking about is the hot pots of Longzhou.",
  ui_story_32160401_26_dialog_content = "Oops...",
  ui_story_32160401_27_dialog_content = "How about shed some light on \"Way of the Artisans\"?",
  ui_story_32160401_28_dialog_content = "Well, I wasn't exactly off-tangent.",
  ui_story_32160401_29_dialog_content = "Who said the pots and pans couldn't be inspirations?",
  ui_story_32160401_30_dialog_content = "It's like the several contraptions we mentioned before...",
  ui_story_32160401_31_dialog_content = "The Blazing Bull is shaped like a bull but able to spit fire, an idea I got from the flame of a hot pot.",
  ui_story_32160401_32_dialog_content = "The Burrowing Dragon had a scorpion frame with a tail to help people dig tunnels, which came from the chimney of the hot pot.",
  ui_story_32160401_33_dialog_content = "The Whirlwind Harrier could land freely even without the wind... Hot pot steams provided the spark.",
  ui_story_32160401_34_dialog_content = "It's more useful to eat hot pot than you think!",
  ui_story_32160401_35_dialog_content = "Hey, that's cheating. You just made it up!",
  ui_story_32160401_36_dialog_content = "It's only a hot pot. How could you get so many design ideas from it?",
  ui_story_32160401_37_dialog_content = "Why you don't give it a try and find out for yourself?",
  ui_story_32160401_38_dialog_content = "To start, let's say we want this hot pot before us to heat up faster...",
  ui_story_32160401_39_dialog_content = "How many ways can we make that happen?",
  ui_story_32160401_40_option_content = "What? Are you grilling me?",
  ui_story_32160401_41_dialog_content = "No, I'd rather be grilling beef.",
  ui_story_32160401_42_dialog_content = "Just think of it as the training for you eventually eating a hot pot alone.",
  ui_story_32160401_43_option_content = "I'm not an artisan so I wouldn't know",
  ui_story_32160401_44_dialog_content = "It's alright to just take guesses.",
  ui_story_32160401_45_dialog_content = "We're only brainstorming, not looking for the right answer.",
  ui_story_32160401_46_dialog_content = "Well... Add more fuel? Make the pot thicker to hold the heat in? Switch to a stove with a better material?",
  ui_story_32160401_47_dialog_content = "That's good! Everything you mentioned...",
  ui_story_32160401_48_dialog_content = "Was enough to get me started on designing the Flame Force contraption.",
  ui_story_32160401_49_dialog_content = "Flame Force contraption... The Blazing Bull?",
  ui_story_32160401_50_dialog_content = "That's right.",
  ui_story_32160401_51_dialog_content = "Like a cow's stomach, it could store more fuel with a quality interior and thin layers to dissipate heat quickly...",
  ui_story_32160401_52_dialog_content = "Ultimately leading to a Clockwork Beast which held plenty of Flame Force in reserve and could heat up instantly.",
  ui_story_32160401_53_dialog_content = "Hey, this stove has heated up perfectly, right on time.",
  ui_story_32160401_54_dialog_content = "Here's the food you two ordered. Enjoy!",
  ui_story_32160401_55_dialog_content = "Thanks!",
  ui_story_32160401_56_dialog_content = "So, you figured out the \"Way of the Artisans\" from the hot pot, right?",
  ui_story_32160401_57_dialog_content = "Now try this new kind of food while it's hot!",
  ui_story_32160401_58_dialog_content = "I'm still feeling a little confused...",
  ui_story_32160401_59_dialog_content = "Why? This ain't your cup of tea?",
  ui_story_32160401_60_dialog_content = "No, I'm going over what you said in my head.",
  ui_story_32160401_61_dialog_content = "You skipped over the essentials, didn't you?",
  ui_story_32160401_62_dialog_content = "If you could really perceive something so arcane from ordinary objects...",
  ui_story_32160401_63_dialog_content = "Wouldn't there be far more artisans than chefs, given the population in Longzhou?",
  ui_story_32160401_64_dialog_content = "Gag...",
  ui_story_32160401_65_dialog_content = "Hahaha...!",
  ui_story_32160401_66_dialog_content = "Stop laughing!",
  ui_story_32160401_67_dialog_content = "I know what you meant:",
  ui_story_32160401_68_dialog_content = "Genius artisans can get inspiration from anything.",
  ui_story_32160401_69_dialog_content = "I agree that's the truth, but I don't think that's the key.",
  ui_story_32160401_70_dialog_content = "No, actually, it's the direct opposite.",
  ui_story_32160401_71_dialog_content = "In regards to gadgetry...",
  ui_story_32160401_72_dialog_content = "Only those who can be inspired by anything other than gadgets can become genius artisans.",
  ui_story_32160401_73_dialog_content = "The real wisdom lies in all things and nature. We just apply it to gadgets.",
  ui_story_32160401_74_dialog_content = "I think I get it but not quite sure...",
  ui_story_32160401_75_dialog_content = "Speaking of nature, why did so many gadgets take the form of animals?",
  ui_story_32160401_76_dialog_content = "Good question.",
  ui_story_32160401_77_dialog_content = "Qianyun, my school of artisanship, believes:",
  ui_story_32160401_78_dialog_content = "No matter how intricate a gadget is, it's nothing compared to the work of nature.",
  ui_story_32160401_79_dialog_content = "The forms and powers of all things and how they reach Lumina are the results of millennia of survival.",
  ui_story_32160401_80_dialog_content = "It's what suits them best right now.",
  ui_story_32160401_81_dialog_content = "So, Qianyun believes that imitating animals is imitating nature. That is the way.",
  ui_story_32160401_82_dialog_content = "Of course, you're not imitating how they look but how they function.",
  ui_story_32160401_83_dialog_content = "Take, for instance, building something that can climb a tree.",
  ui_story_32160401_84_dialog_content = "The key is not to make it look like a monkey, but how the monkey's limbs work.",
  ui_story_32160401_85_dialog_content = "See how they move, duplicate how they act, and finally get the result you want.",
  ui_story_32160401_86_dialog_content = "I see... It sounds like the emerging simulacrum theory from certain Illumina labs.",
  ui_story_32160401_87_dialog_content = "Close, though the artisans in Longzhou have been working on it for thousands of years.",
  ui_story_32160401_88_dialog_content = "I guess that's one of the reasons why the two sides are moving in different directions.",
  ui_story_32160401_89_dialog_content = "Yes, I'm a lot more clear now.",
  ui_story_32160401_90_dialog_content = "What about gadgets that don't look like animals? Such as...",
  ui_story_32160401_91_dialog_content = "Such as the Peculiar Parasol?",
  ui_story_32160401_92_dialog_content = "Yes!",
  ui_story_32160401_93_dialog_content = "Well, that's because the principles behind it involved more than just the Qianyun school of design...",
  ui_story_32160401_94_dialog_content = "But the Dikun way as well.",
  ui_story_32160401_95_dialog_content = "Dikun is completely different from Qianyun.",
  ui_story_32160401_96_dialog_content = "They believe all things grown naturally are inherently flawed.",
  ui_story_32160401_97_dialog_content = "Creatures swimming in the sea die when they're out of water. Flying creatures are fragile. Ground creatures are land-bound.",
  ui_story_32160401_98_dialog_content = "Only artificial creations can be free of defects. Only we can make perfection happen.",
  ui_story_32160401_99_dialog_content = "And because you don't have to mess with perfection, it must be inanimate.",
  ui_story_32160401_100_dialog_content = "Which is why they don't stick to the old school of making their creations resemble animals.",
  ui_story_32160401_101_dialog_content = "So they tend to make mostly traps and passive gadgets, eventually adding gunpowder to the mix.",
  ui_story_32160401_102_dialog_content = "You don't sound like you're against Dikun?",
  ui_story_32160401_103_dialog_content = "Why should I be? That's wisdom from all the artisans before I was born too.",
  ui_story_32160401_104_dialog_content = "It helped me a lot, as much as the hot pot.",
  ui_story_32160401_105_dialog_content = "If you want to know, I'm against the current status quo between the two schools.",
  ui_story_32160401_106_dialog_content = "They bicker and argue forever, getting evermore away from the art.",
  ui_story_32160401_107_dialog_content = "But the thing is: they're not even fighting over making better contraptions.",
  ui_story_32160401_108_dialog_content = "Instead, they want people to acknowledge their superiority, so their respective students will look more dignified to the king.",
  ui_story_32160401_109_dialog_content = "Spats like that are what stagnate the gadget-building techniques in the Ye Kingdom...",
  ui_story_32160401_110_dialog_content = "That's why I made the parasol, simply to prove how meaningless their dispute is.",
  ui_story_32160401_111_dialog_content = "Is that why it's your favorite and you carry it every day?",
  ui_story_32160401_112_dialog_content = "That's right. It has the pro from both schools.",
  ui_story_32160401_113_dialog_content = "It imitates functionality and is versatile. It's also portable, like certain gadgets.",
  ui_story_32160401_114_dialog_content = "This parasol holds copper dragonflies and clockwork birds, as well as darts and beads.",
  ui_story_32160401_115_dialog_content = "Active and passive, both schools are all in one. You can call it my magnum opus.",
  ui_story_32160401_116_dialog_content = "Interesting... That makes me itching to make my own gadget.",
  ui_story_32160401_117_dialog_content = "Well, although I recognize your talent and smarts...",
  ui_story_32160401_118_dialog_content = "It's not that easy to start from scratch with no experience whatsoever.",
  ui_story_32160401_119_option_content = "Teach me, Xuan Ji! No... Master Xuan Ji!",
  ui_story_32160401_120_dialog_content = "Stop buttering me up! Well, I can show you something simple. Count that as me returning the favor.",
  ui_story_32160401_121_dialog_content = "So you won't think I'm only good for hot pots.",
  ui_story_32160401_122_option_content = "Okay. What's a simple start I can do?",
  ui_story_32160401_123_dialog_content = "Let me think... Ah, got it.",
  ui_story_32160401_124_dialog_content = "The heart locket I made before. We'll start with that.",
  ui_story_32160401_125_dialog_content = "Heart locket...?",
  ui_story_32160401_126_dialog_content = "It's a puzzle toy of the Ye Kingdom, with crisscrossing locking mechanisms. It's the simplest gadget.",
  ui_story_32160401_127_dialog_content = "But this one is no longer something normal people can solve after I got through with it.",
  ui_story_32160401_128_dialog_content = "So I have to figure it out?",
  ui_story_32160401_129_dialog_content = "Heh, relax! Just play around with it.",
  ui_story_32160401_130_dialog_content = "Once you've played with it enough, insight will start to come...",
  ui_story_32160601_1_dialog_content = "That ought to complete my records!",
  ui_story_32160601_2_dialog_content = "Thanks again for your help today, PlayerName.",
  ui_story_32160601_3_dialog_content = "I didn't realize the Colossus could give me such a clear view of the night sky. It's a huge help.",
  ui_story_32160601_4_dialog_content = "Don't mention it. All I did was adjust the projection a little.",
  ui_story_32160601_5_dialog_content = "Besides, I enjoy seeing it too.",
  ui_story_32160601_6_dialog_content = "So you also like looking at the stars?",
  ui_story_32160601_7_dialog_content = "Yep!",
  ui_story_32160601_8_dialog_content = "When I was still buried underground, Soroz would show me images of the outside world.",
  ui_story_32160601_9_dialog_content = "But when I finally saw the stars for myself, I realized just how far they truly were...",
  ui_story_32160601_10_dialog_content = "Honestly, it made me feel a little sad.",
  ui_story_32160601_11_dialog_content = "But there's no changing that, right? So...",
  ui_story_32160601_12_dialog_content = "Are you developing some kind of new machine with all of this research?",
  ui_story_32160601_13_dialog_content = "That's right! After all, the Spring Festival is right around the corner.",
  ui_story_32160601_14_dialog_content = "Huh? What does it have to do with the Spring Festival?",
  ui_story_32160601_15_dialog_content = "Remember that I study under the Qianyun sect?",
  ui_story_32160601_16_dialog_content = "If we're not working on something urgent, disciples such as myself are supposed to visit our master during the Spring Festival.",
  ui_story_32160601_17_dialog_content = "That way, we can flaunt—I mean demonstrate the fruits of our work for that year.",
  ui_story_32160601_18_dialog_content = "That's why whenever the festival comes around, I feel a growing need to work on something even greater.",
  ui_story_32160601_19_dialog_content = "Sounds interesting.",
  ui_story_32160601_20_dialog_content = "I'd really like to take a look at Qianyun sect someday.",
  ui_story_32160601_21_dialog_content = "The Ye Kingdom, where technology reigns supreme... It must be a really special place!",
  ui_story_32160601_22_dialog_content = "Wait, speaking of the Spring Festival... You're not going back this year, are you? Is that really okay?",
  ui_story_32160601_23_dialog_content = "Nothing I can do about it!",
  ui_story_32160601_24_dialog_content = "I'd love to take you back and show you around, but it's just too long of a journey to get there.",
  ui_story_32160601_25_dialog_content = "That's a shame.",
  ui_story_32160601_26_dialog_content = "But...",
  ui_story_32160601_27_dialog_content = "But?",
  ui_story_32160601_28_dialog_content = "I just got struck by inspiration!",
  ui_story_32160601_29_dialog_content = "I'll tell you all about my ideas sometime soon, I promise!",
  ui_story_32160601_30_dialog_content = "<color=#e8d9bb>A few days later</color>",
  ui_story_32160601_31_dialog_content = "(Xuan Ji's letter told me to come to this place.)",
  ui_story_32160601_32_dialog_content = "(But I don't see anything around here.)",
  ui_story_32160601_33_dialog_content = "Click—",
  ui_story_32160601_34_dialog_content = "A fire crab? What's it doing here?!",
  ui_story_32160601_35_dialog_content = "Click, click—",
  ui_story_32160601_36_dialog_content = "Is it telling me to go over there?",
  ui_story_32160601_37_dialog_content = "Chirp!",
  ui_story_32160601_38_dialog_content = "It's pointing with its wings... This way, right?",
  ui_story_32160601_39_dialog_content = "Buzz—",
  ui_story_32160601_40_dialog_content = "Where are you taking me?!",
  ui_story_32160601_41_dialog_content = "H-Hey, we can't just barge into other people's rooms—",
  ui_story_32160601_42_dialog_content = "Wait, is this...?",
  ui_story_32160601_43_dialog_content = "Oh good, you brought PlayerName!",
  ui_story_32160601_44_dialog_content = "Could you please tell me what's going on—",
  ui_story_32160601_45_dialog_content = "Xuan... Ji?",
  ui_story_32160601_46_dialog_content = "What's the matter? Don't recognize me?",
  ui_story_32160601_47_dialog_content = "No, it's just your style is a little different than usual today.",
  ui_story_32160601_48_dialog_content = "These are the traditional garments of Qianyun sect disciples. Comfortable and convenient, right?",
  ui_story_32160601_49_dialog_content = "Unfortunately, since everyone wears the same exact outfit, our clothes lose a little bit of their uniqueness.",
  ui_story_32160601_50_dialog_content = "I think they suit you just fine, Xuan Ji.",
  ui_story_32160601_51_dialog_content = "It almost feels like you've gone back in time to a time before we knew each other.",
  ui_story_32160601_52_dialog_content = "Heheh, if that's how you feel, then I'll have to wear this outfit a little more often.",
  ui_story_32160601_53_dialog_content = "Wait, so does that mean this room is also...",
  ui_story_32160601_54_dialog_content = "That's right! It's a replica of my workshop at Qianyun!",
  ui_story_32160601_55_dialog_content = "Since I couldn't go back this year, I figured I may as well bring part of them to me!",
  ui_story_32160601_56_dialog_content = "That makes sense, right?",
  ui_story_32160601_57_dialog_content = "Sure does... Wait, no!",
  ui_story_32160601_58_dialog_content = "This may look like your workshop, but none of your fellow disciples are here!",
  ui_story_32160601_59_dialog_content = "How are you supposed to show them your work for the year?",
  ui_story_32160601_60_dialog_content = "Oh, that's fine by me.",
  ui_story_32160601_61_dialog_content = "Why do you think it's so important for me to share my work with others?",
  ui_story_32160601_62_dialog_content = "Well, machines can be really complicated, so coming together with other people is a great way to learn... Right?",
  ui_story_32160601_63_dialog_content = "Correct.",
  ui_story_32160601_64_dialog_content = "In other words, as long as people can understand each other, they can also learn from each other regardless of sect or background.",
  ui_story_32160601_65_dialog_content = "Also...",
  ui_story_32160601_66_dialog_content = "This parasol that I'm working on isn't meant for them to begin with.",
  ui_story_32160601_67_dialog_content = "By borrowing a few concepts from the armillary sphere and simplifying their structures, then applying the information gained from the Colossus' star projections...",
  ui_story_32160601_68_dialog_content = "I can produce the movements of stars with this parasol.",
  ui_story_32160601_69_option_content = "I-It's beautiful!",
  ui_story_32160601_70_dialog_content = "If I didn't know, I'd think it was a piece of artwork or something.",
  ui_story_32160601_71_dialog_content = "Your praise is most appreciated!",
  ui_story_32160601_72_option_content = "It's more than just beautiful.",
  ui_story_32160601_73_dialog_content = "... I'm sorry, Xuan Ji.",
  ui_story_32160601_74_dialog_content = "Huh? Why are you apologizing?",
  ui_story_32160601_75_dialog_content = "I really want to offer my praises, but I can't think of the right words to say.",
  ui_story_32160601_76_dialog_content = "The word \"beautiful\" doesn't even begin to describe the feeling of mystery and exploration of the night sky...",
  ui_story_32160601_77_dialog_content = "That sounds like a great way to put it already!",
  ui_story_32160601_78_dialog_content = "Come here.",
  ui_story_32160601_79_dialog_content = "Huh?",
  ui_story_32160601_80_dialog_content = "The best way to stargaze is while lying on your back, right?",
  ui_story_32160601_81_dialog_content = "D-Don't you think this is a little too close—",
  ui_story_32160601_82_dialog_content = "Can you see the seven stars of the Big Dipper?",
  ui_story_32160601_83_dialog_content = "It takes an entire year for the handle to cycle once and return to its original position. That's how we know when spring has arrived.",
  ui_story_32160601_84_dialog_content = "In other words, the Spring Festival?",
  ui_story_32160601_85_dialog_content = "That's right. A new cycle for a new year.",
  ui_story_32160601_86_dialog_content = "That's why people offer gifts to each other on this day. It's their way of thanking each other for the past while looking forward to a prosperous future.",
  ui_story_32160601_87_dialog_content = "I've been thinking about what to give you for a very long time.",
  ui_story_32160601_88_dialog_content = "Until that day, you said the stars were much farther from us than you thought.",
  ui_story_32160601_89_dialog_content = "... I didn't really mean anything by that, you know.",
  ui_story_32160601_90_dialog_content = "Oh, I beg to differ.",
  ui_story_32160601_91_dialog_content = "Our creation myth says that when chaos first appeared, yin and yang were separated, and people were both ignorant and uncivilized.",
  ui_story_32160601_92_dialog_content = "But then one day, a sage began looking to the stars for guidance. By measuring and tracing their movements, time and year were determined, and everything fell into order.",
  ui_story_32160601_93_dialog_content = "The stars guide us in myriad ways, yet they lie forever beyond our reach.",
  ui_story_32160601_94_dialog_content = "No matter how much we reach, no matter how tall we stand, we can never touch them.",
  ui_story_32160601_95_dialog_content = "For that reason, the night sky has always been a dream of sorts to every living being.",
  ui_story_32160601_96_dialog_content = "And today, I've finally managed to bring that dream a little closer to reality.",
  ui_story_32160601_97_dialog_content = "PlayerName. My dear friend.",
  ui_story_32160601_98_dialog_content = "I would like to present you with this parasol, as well as the dream it represents.",
  ui_story_32160601_99_dialog_content = "Whether it's a faraway land, or the ever distant stars above...",
  ui_story_32160601_100_dialog_content = "I hope my gift reminds you that nothing is truly out of reach.",
  ui_story_32160601_101_dialog_content = "If you ever need me someday, and I've gone someplace far away from you...",
  ui_story_32160601_102_dialog_content = "Keep this parasol at your side and we'll always be close to one another, no matter the distance.",
  ui_story_32160601_103_dialog_content = "... Oh my.",
  ui_story_32160601_104_dialog_content = "I just wish I knew what to give you in exchange for something this precious.",
  ui_story_32160601_105_dialog_content = "Hahaha, I'm just happy that you like it.",
  ui_story_32160601_106_dialog_content = "I may not know what kind of inventions your fellow disciples usually create.",
  ui_story_32160601_107_dialog_content = "But anyone would be incredibly proud of this parasol. It's an absolute masterpiece.",
  ui_story_32160601_108_dialog_content = "I agree with you there.",
  ui_story_32160601_109_dialog_content = "By the way, these stars...",
  ui_story_32160601_110_dialog_content = "(The stars twinkled just within reach, and the soft sound of turning gears reached our ears.)",
  ui_story_32160601_111_dialog_content = "(In that quiet space, Xuan Ji told me all about Longzhou's stories regarding the stars.)",
  ui_story_32160601_112_dialog_content = "(It was so peaceful that before I knew it, I started feeling sleepy.)",
  ui_story_32160601_113_dialog_content = "Getting tired? Go ahead and sleep, if you want.",
  ui_story_32160601_114_dialog_content = "Don't worry. There's nothing to be afraid of when you're under my parasol.",
  ui_story_32160601_115_dialog_content = "Whether we're facing a howling storm or a horde of wicked spirits, I'll always protect this little corner of the world.",
  ui_story_32160601_116_dialog_content = "After all, underneath this parasol...",
